/**
 * The publish panel's text rules, with no React. The metadata and its rows
 * are generated by the server (SUMTAB-08).
 */
import type { MetadataRowResponse, PublicationSendResponse } from "@/client"
import type { PublishingOptions } from "@/types"

export const partsLabel = (n: number) => `${n} message${n === 1 ? "" : "s"}`

/** What a send's answer tells the publisher. */
export function publicationToast(result: PublicationSendResponse): {
  kind: "success" | "error"
  text: string
} {
  if (result.status === "success")
    return {
      kind: "success",
      text: `Published ${partsLabel(result.partsTotal)}.`,
    }
  return {
    kind: "error",
    text: `Publishing stopped after ${result.partsSent} of ${partsLabel(result.partsTotal)}: ${result.error}`,
  }
}

/** The rows to leave out once `key` is ticked or unticked. */
export function omittedAfterToggle(
  rows: MetadataRowResponse[],
  key: string,
): string[] {
  return rows
    .filter((r) => (r.key === key ? r.sent : !r.sent))
    .map((r) => r.key)
}

/** What a Summary publishes with: its own options over the Account's. */
export function summaryPublishing(
  own: Partial<PublishingOptions>,
  defaults: PublishingOptions,
): PublishingOptions {
  return {
    citationStyle: own.citationStyle ?? defaults.citationStyle,
    linkPreviews: own.linkPreviews ?? defaults.linkPreviews,
    timeZone: own.timeZone ?? defaults.timeZone,
  }
}

/**
 * The Summary's own options once `change` is picked, or null when it picks
 * what the Summary already publishes with: that changes nothing, so it does
 * not stop the Summary following Settings.
 */
export function publishingAfterChange(
  own: Partial<PublishingOptions>,
  current: PublishingOptions,
  change: Partial<PublishingOptions>,
): Partial<PublishingOptions> | null {
  const same = Object.entries(change).every(
    ([key, value]) => current[key as keyof PublishingOptions] === value,
  )
  return same ? null : { ...own, ...change }
}
